begin;
create type public.work_order_status as enum('open','scheduled','in_progress','completed','cancelled');
create table public.work_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,order_number text not null,type text not null,description text not null,priority text not null default 'normal' check(priority in('low','normal','high','urgent')),subscriber_id uuid references subscribers(id),connection_id uuid references water_connections(id),assigned_to uuid references profiles(id),status work_order_status not null default 'open',scheduled_at timestamptz,completed_at timestamptz,notes text,created_by uuid not null references profiles(id),created_at timestamptz not null default now(),unique(organization_id,order_number));
create table public.inventory_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,code text not null,name text not null,unit text not null,quantity numeric(14,3) not null default 0,minimum_stock numeric(14,3) not null default 0,unit_cost numeric(14,2) not null default 0,active boolean not null default true,created_by uuid not null references profiles(id),created_at timestamptz not null default now(),unique(organization_id,code));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,item_id uuid not null references inventory_items(id),work_order_id uuid references work_orders(id),movement_type text not null check(movement_type in('entry','exit','adjustment')),quantity numeric(14,3) not null check(quantity>0),reason text not null,created_by uuid not null references profiles(id),created_at timestamptz not null default now());
insert into permissions(code,description) values('operations.read','Consultar operaciones'),('operations.manage','Administrar órdenes'),('inventory.read','Consultar inventario'),('inventory.manage','Administrar inventario') on conflict(code) do update set description=excluded.description;
insert into role_permissions(role_id,permission_code) select r.id,p.code from roles r cross join permissions p where r.code='superadmin' and p.code in('operations.read','operations.manage','inventory.read','inventory.manage') on conflict do nothing;
alter table work_orders enable row level security;alter table inventory_items enable row level security;alter table inventory_movements enable row level security;create policy work_read on work_orders for select using(organization_id=current_organization_id() and has_permission('operations.read'));create policy inv_read on inventory_items for select using(organization_id=current_organization_id() and has_permission('inventory.read'));create policy invmov_read on inventory_movements for select using(organization_id=current_organization_id() and has_permission('inventory.read'));revoke insert,update,delete on work_orders,inventory_items,inventory_movements from authenticated;
create or replace function public.create_work_order(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare r work_orders;begin if not has_permission('operations.manage') then raise exception 'FORBIDDEN';end if;if length(trim(coalesce(p_payload->>'description','')))<5 then raise exception 'DESCRIPTION_REQUIRED';end if;insert into work_orders(organization_id,order_number,type,description,priority,subscriber_id,connection_id,assigned_to,scheduled_at,created_by) values(current_organization_id(),next_document_number('work_order','OT',5),trim(p_payload->>'type'),trim(p_payload->>'description'),coalesce(nullif(p_payload->>'priority',''),'normal'),nullif(p_payload->>'subscriber_id','')::uuid,nullif(p_payload->>'connection_id','')::uuid,nullif(p_payload->>'assigned_to','')::uuid,nullif(p_payload->>'scheduled_at','')::timestamptz,auth.uid()) returning * into r;perform write_audit_event('work_order.create','work_orders',r.id::text,null,to_jsonb(r),null);return to_jsonb(r);end$$;
create or replace function public.update_work_order(p_id uuid,p_status text,p_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$declare old work_orders;r work_orders;begin if not has_permission('operations.manage') then raise exception 'FORBIDDEN';end if;select * into old from work_orders where id=p_id and organization_id=current_organization_id() for update;if old.id is null then raise exception 'NOT_FOUND';end if;update work_orders set status=p_status::work_order_status,notes=coalesce(p_notes,notes),completed_at=case when p_status='completed' then now() else completed_at end where id=p_id returning * into r;perform write_audit_event('work_order.update','work_orders',r.id::text,to_jsonb(old),to_jsonb(r),p_notes);return to_jsonb(r);end$$;
create or replace function public.list_work_orders() returns setof jsonb language sql stable security definer set search_path=public as $$select to_jsonb(w) from work_orders w where organization_id=current_organization_id() and has_permission('operations.read') order by created_at desc$$;
create or replace function public.create_inventory_item(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare r inventory_items;begin if not has_permission('inventory.manage') then raise exception 'FORBIDDEN';end if;insert into inventory_items(organization_id,code,name,unit,minimum_stock,unit_cost,created_by) values(current_organization_id(),upper(trim(p_payload->>'code')),trim(p_payload->>'name'),trim(p_payload->>'unit'),coalesce((p_payload->>'minimum_stock')::numeric,0),coalesce((p_payload->>'unit_cost')::numeric,0),auth.uid()) returning * into r;perform write_audit_event('inventory.create','inventory_items',r.id::text,null,to_jsonb(r),null);return to_jsonb(r);end$$;
create or replace function public.list_inventory() returns setof jsonb language sql stable security definer set search_path=public as $$select to_jsonb(i) from inventory_items i where organization_id=current_organization_id() and active and has_permission('inventory.read') order by name$$;
create or replace function public.register_inventory_movement(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare r inventory_movements;q numeric;t text;item inventory_items;begin if not has_permission('inventory.manage') then raise exception 'FORBIDDEN';end if;q=(p_payload->>'quantity')::numeric;t=p_payload->>'movement_type';if q<=0 or t not in('entry','exit','adjustment') then raise exception 'INVALID_MOVEMENT';end if;select * into item from inventory_items where id=(p_payload->>'item_id')::uuid and organization_id=current_organization_id() for update;if item.id is null then raise exception 'ITEM_NOT_FOUND';end if;if t='exit' and item.quantity<q then raise exception 'INSUFFICIENT_STOCK';end if;update inventory_items set quantity=case when t='entry' then quantity+q when t='exit' then quantity-q else q end where id=item.id;insert into inventory_movements(organization_id,item_id,work_order_id,movement_type,quantity,reason,created_by) values(current_organization_id(),item.id,nullif(p_payload->>'work_order_id','')::uuid,t,q,trim(p_payload->>'reason'),auth.uid()) returning * into r;perform write_audit_event('inventory.movement','inventory_movements',r.id::text,null,to_jsonb(r),null);return to_jsonb(r);end$$;
commit;
